import{_ as t,o as a,c as s,a6 as n}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"上下文与控制字段","description":"User-Agent、Server、Referer、Retry-After、Allow、Link 等字段的语法与约束。","frontmatter":{"title":"上下文与控制字段","description":"User-Agent、Server、Referer、Retry-After、Allow、Link 等字段的语法与约束。","source":"https://daiw.org/manual/http11/context-fields"},"headers":[],"relativePath":"manual/computer-programming/http11/context-fields.md","filePath":"manual/computer-programming/http11/context-fields.md"}'),r={name:"manual/computer-programming/http11/context-fields.md"};function i(o,e,l,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="上下文与控制字段" tabindex="-1">上下文与控制字段 <a class="header-anchor" href="#上下文与控制字段" aria-label="Permalink to &quot;上下文与控制字段&quot;">​</a></h1><h2 id="user-agent" tabindex="-1">User-Agent <a class="header-anchor" href="#user-agent" aria-label="Permalink to &quot;User-Agent&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-Agent = product *( RWS ( product / comment ) )</span></span>
<span class="line"><span>product    = token [ &quot;/&quot; product-version ]</span></span>
<span class="line"><span>comment    = &quot;(&quot; *( ctext / quoted-pair / comment ) &quot;)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>产品按<strong>重要性降序</strong>排列。</li><li><code>comment</code> 用圆括号，<strong>可嵌套</strong>——解析时必须配对计数，不能简单找第一个 <code>)</code>。</li><li>浏览器 UA 因历史兼容原因几乎全部谎报（都以 <code>Mozilla/5.0</code> 开头），<strong>不应</strong>用于功能判断——用特性检测或 Client Hints。</li><li><strong>MUST NOT</strong> 用于安全决策；客户端可任意伪造。</li></ul><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server = product *( RWS ( product / comment ) )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>语法同 <code>User-Agent</code>，用于响应。</p><p><strong>SHOULD</strong> 精简：暴露精确版本号（<code>Server: nginx/1.24.0</code>）便于攻击者匹配已知漏洞。生产环境宜只留产品名或完全移除。</p><h2 id="referer" tabindex="-1">Referer <a class="header-anchor" href="#referer" aria-label="Permalink to &quot;Referer&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Referer = absolute-URI / partial-URI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>请求的来源页面 URI。<strong>注意拼写</strong>——规范中就是错拼的 <code>Referer</code>（少一个 r），不可写成 <code>Referrer</code>。</p><p>强制约束：</p><ul><li><strong>MUST NOT</strong> 含 fragment。</li><li><strong>MUST NOT</strong> 含 <code>userinfo</code>（<code>user:pass@</code>）。</li><li>从 <strong>HTTPS 页面跳到 HTTP</strong> 时 <strong>MUST NOT</strong> 发送——防止泄露安全上下文的 URL。</li><li>客户端 <strong>MAY</strong> 完全省略以保护隐私。</li></ul><p>现代浏览器由 <code>Referrer-Policy</code>（拼写正确的那个，属 W3C 规范而非 HTTP 核心）控制发送粒度，默认多为 <code>strict-origin-when-cross-origin</code>（跨源时只发 origin）。</p><p>URL 里带令牌/会话 ID 会经由 <code>Referer</code> 泄露给第三方——这是<a href="/Front2Full/manual/computer-programming/http11/authentication">不把凭据放 query</a> 的直接原因。</p><h2 id="from" tabindex="-1">From <a class="header-anchor" href="#from" aria-label="Permalink to &quot;From&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>From = mailbox</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>发起请求者的<strong>人类</strong>邮箱地址（RFC 5322 格式），用于爬虫标注联系方式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>From: [email protected]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>不是</strong>认证字段，无任何鉴权语义。</li><li>因隐私原因，浏览器<strong>从不</strong>发送。</li></ul><h2 id="allow" tabindex="-1">Allow <a class="header-anchor" href="#allow" aria-label="Permalink to &quot;Allow&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Allow = #method</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>响应字段，列出目标资源支持的方法。</p><ul><li><code>405</code> 响应中 <strong>MUST</strong> 出现。</li><li><code>OPTIONS</code> 响应中 <strong>SHOULD</strong> 出现。</li><li>空值合法，表示不允许任何方法。</li><li>该字段可被缓存，方法集变化时需注意失效。</li></ul><h2 id="retry-after" tabindex="-1">Retry-After <a class="header-anchor" href="#retry-after" aria-label="Permalink to &quot;Retry-After&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Retry-After = HTTP-date / delay-seconds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>两种形式，接收方必须都能解析：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Retry-After: 120</span></span>
<span class="line"><span>Retry-After: Wed, 21 Oct 2026 07:28:00 GMT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>判别方式：<strong>以数字开头即为秒数</strong>（日期形式恒以字母开头的星期缩写起始）。</p><p>适用状态码：</p><table tabindex="0"><thead><tr><th>码</th><th>含义</th></tr></thead><tbody><tr><td><code>503</code></td><td>服务多久后恢复</td></tr><tr><td><code>429</code></td><td>多久后可再请求</td></tr><tr><td><code>301</code>/<code>3xx</code></td><td>资源多久后可用（罕见）</td></tr></tbody></table><p>客户端<strong>应</strong>遵循该值，并在其基础上加<strong>随机抖动</strong>——大量客户端在同一秒重试会造成二次雪崩。</p><h2 id="link" tabindex="-1">Link <a class="header-anchor" href="#link" aria-label="Permalink to &quot;Link&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Link       = #link-value</span></span>
<span class="line"><span>link-value = &quot;&lt;&quot; URI-Reference &quot;&gt;&quot; *( OWS &quot;;&quot; OWS link-param )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>RFC 8288。以机器可读方式表达资源间关系：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Link: &lt;/style.css&gt;; rel=preload; as=style</span></span>
<span class="line"><span>Link: &lt;https://api.example.com/page/2&gt;; rel=&quot;next&quot;</span></span>
<span class="line"><span>Link: &lt;https://legal.example&gt;; rel=&quot;blocked-by&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>URI <strong>必须</strong>用尖括号包围。</li><li><code>rel</code> 取值来自 IANA Link Relation 注册表（<code>next</code>、<code>prev</code>、<code>canonical</code>、<code>preload</code>、<code>alternate</code>…）。</li><li>多个关系用空格分隔并加引号：<code>rel=&quot;alternate stylesheet&quot;</code>。</li><li>用于 <code>103 Early Hints</code>（预加载）与 <code>451</code>（<code>rel=&quot;blocked-by&quot;</code>）。</li></ul><h2 id="host-回顾" tabindex="-1">Host（回顾） <a class="header-anchor" href="#host-回顾" aria-label="Permalink to &quot;Host（回顾）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host = uri-host [ &quot;:&quot; port ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>已在<a href="/Front2Full/manual/computer-programming/http11/request-line">请求行</a>详述，此处仅列关键约束：</p><ul><li>HTTP/1.1 请求 <strong>MUST</strong> 包含，且<strong>有且仅有一个</strong>；缺失或重复 → <code>400</code>。</li><li>出现在 absolute-form 时，以 request-target 中的 authority 为准。</li><li>端口与方案默认端口相同时可省略。</li><li>是虚拟主机路由的依据，<strong>必须</strong>校验白名单——否则产生 Host 头注入（污染密码重置链接等）。</li></ul><h2 id="其他常见字段一览" tabindex="-1">其他常见字段一览 <a class="header-anchor" href="#其他常见字段一览" aria-label="Permalink to &quot;其他常见字段一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>方向</th><th>语法要点</th></tr></thead><tbody><tr><td><code>Date</code></td><td>响应（请求可选）</td><td>见<a href="/Front2Full/manual/computer-programming/http11/http-date">日期</a></td></tr><tr><td><code>Location</code></td><td>响应</td><td>见<a href="/Front2Full/manual/computer-programming/http11/status-3xx">3xx</a></td></tr><tr><td><code>Expect</code></td><td>请求</td><td>见<a href="/Front2Full/manual/computer-programming/http11/connection-management">连接管理</a></td></tr><tr><td><code>Accept-Patch</code></td><td>响应</td><td><code>#media-type</code>，声明支持的补丁格式</td></tr><tr><td><code>Content-Disposition</code></td><td>响应</td><td>RFC 6266。<code>attachment; filename=&quot;x&quot;</code>；非 ASCII 用 <code>filename*=UTF-8&#39;&#39;...</code></td></tr><tr><td><code>Alt-Svc</code></td><td>响应</td><td>RFC 7838。声明可用的替代服务（HTTP/2、HTTP/3 发现）</td></tr></tbody></table><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理与转发字段</a>。</p>`,45)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
